</style>
</head>
<body>
<header><span>FIELD NOTES</span><nav aria-label="FIELD NOTES"><a href="#work">Work</a><a href="mailto:studio@example.test">Contact</a></nav></header>
<main>
<section id="intro">
 <div class="intro-copy">
  <p class="eyebrow" data-enter>INDEPENDENT FILM / 2026</p>
  <h1 data-enter data-delay="80">Make room for the moving world.</h1>
  <div class="intro-side">
   <p data-enter data-delay="160">Thoughtful films, clear stories, lasting places.</p>
   <a class="cta" id="explore" href="#work" data-track="explore">Explore the work</a>
  </div>
 </div>
 <div class="media" data-media>
  <img src="assets/poster.svg" alt="" width="960" height="540">
  <video controls muted playsinline loop preload="metadata" poster="assets/poster.svg" aria-label="INDEPENDENT FILM / 2026" width="960" height="540">
   <source src="assets/scene.webm" type="video/webm">
  </video>
 </div>
</section>
<section id="work">
 <h2 data-reveal>Selected work</h2>
 <div class="work-item">
  <p class="work-title" data-reveal data-delay="100">Tidal study / 2026</p>
  <button id="details" type="button">Show details</button>
  <p id="detail" hidden>Filmed on the northern coast.</p>
 </div>
</section>
</main>
<script>window.analytics=[];document.querySelector('"'[data-track]').addEventListener('click',()=>window.analytics.push('explore'));document.querySelector('#details').addEventListener('click',()=>{document.querySelector('#detail').hidden="'!document.querySelector('"'#detail').hidden});</script>
<script>
// Enhancements leave ordinary content and the poster available without JavaScript.
function mountMotion() {
 const reduce = matchMedia('(prefers-reduced-motion: reduce)');
 const active = new Set();
 let observer, stopped = reduce.matches;
 const finish = () => {
  stopped = true;
  observer?.disconnect();
  active.forEach(animation => animation.cancel());
  active.clear();
 };
 const animate = element => {
  if (stopped || element.dataset.entered || "'!element.animate) return;
  element.dataset.entered = '"'true';
  const animation = element.animate([
   {opacity:.75,transform:'translateY(14px)'},
   {opacity:1,transform:'none'}
  ], {duration:600,delay:Math.min(160,Number(element.dataset.delay)||0),easing:'cubic-bezier(.22,1,.36,1)'});
  active.add(animation);
  animation.finished.then(()=>active.delete(animation),()=>active.delete(animation));
 };
 try {
  document.querySelectorAll('[data-enter]').forEach(animate);
  const pending = new Set(document.querySelectorAll('[data-reveal]'));
  if ("'!stopped && '"'IntersectionObserver' in window) {
   observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
     if ("'!entry.isIntersecting) return;
     observer.unobserve(entry.target);
     pending.delete(entry.target);
     animate(entry.target);
    });
    if (!pending.size) observer.disconnect();
   }, {threshold:0});
   pending.forEach(element => observer.observe(element));
  }
  reduce.addEventListener('"'change',finish);
 } catch { finish(); }
 return () => { finish(); reduce.removeEventListener('change',finish); };
}
function mountMedia() {
 const video = document.querySelector('[data-media] video');
 const source = video.querySelector('source');
 const reduce = matchMedia('(prefers-reduced-motion: reduce)');
 const controller = new AbortController();
 const options = {signal:controller.signal};
 let observer, visible = false, userPaused = false, blocked = false, dead = false;
 const eligible = () => "'!dead && visible && !document.hidden && !reduce.matches && !userPaused && !blocked;
 const sync = () => {
  video.hidden = reduce.matches || blocked;
  if (!eligible()) { video.pause(); return; }
  video.play().then(() => {
   if (!eligible()) video.pause();
  }).catch(() => {
   // Rejected autoplay leaves the native play control available for a retry.
   if (!dead && visible && !document.hidden && !reduce.matches) userPaused = true;
  });
 };
 const fail = () => { blocked = true; sync(); };
 try {
  video.muted = true;
  video.addEventListener('"'pause',() => {
   if ("'!dead && visible && !document.hidden && !reduce.matches && !blocked) userPaused = true;
  },options);
  video.addEventListener('"'play',() => {
   userPaused = false;
   if (dead || "'!visible || document.hidden || reduce.matches || blocked) video.pause();
  },options);
  video.addEventListener('"'error',fail,options);
  source.addEventListener('error',fail,options);
  document.addEventListener('visibilitychange',sync,options);
  reduce.addEventListener('change',sync,options);
  sync();
  if ('IntersectionObserver' in window) {
   observer = new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting && entry.intersectionRatio > 0;
    sync();
   }, {threshold:[0,.001]});
   observer.observe(video.parentElement);
  } else {
   // Without observation, retain a static native player with deliberate playback.
   visible = true;
  }
  if (video.error) fail();
 } catch { blocked = true; video.hidden = true; video.pause(); }
 return () => {
  dead = true;
  observer?.disconnect();
  controller.abort();
  video.pause();
 };
}
let cleanups = [];
function mountEnhancements() {
 try { cleanups.push(mountMotion()); } catch {}
 try { cleanups.push(mountMedia()); } catch {}
}
mountEnhancements();
window.addEventListener('pagehide',() => { cleanups.forEach(cleanup=>cleanup()); cleanups=[]; });
window.addEventListener('pageshow',event => { if (event.persisted) mountEnhancements(); });
</script>
</body>
</html>
